import{c as t,Q as r,j as n,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Pre-event checklist","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/pre-event-checklist.md","filePath":"user/event-setup/pre-event-checklist.md"}'),i={name:"user/event-setup/pre-event-checklist.md"};function s(o,e,l,h,c,d){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="pre-event-checklist" tabindex="-1">Pre-event checklist <a class="header-anchor" href="#pre-event-checklist" aria-label="Permalink to &quot;Pre-event checklist&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers making sure everything is ready before event day.</p><p>A printable checklist of what to do in the weeks, days and hours before a competition. Each item links to the page that explains it. Skip what your event doesn&#39;t use: a club event with no radios has no meshO Prime to test.</p><h2 id="weeks-before" tabindex="-1">Weeks before <a class="header-anchor" href="#weeks-before" aria-label="Permalink to &quot;Weeks before&quot;">​</a></h2><p><strong>The event</strong></p><ul><li>[ ] Create the event, from Eventor or by hand, and check its date, type and discipline. The type can&#39;t be changed afterwards. See <a href="./create-event">Creating an event</a> and <a href="./create-event-from-eventor">Creating an event from Eventor</a>.</li><li>[ ] For a carnival or a knock-out, create the <a href="./multi-stage-events">multi-stage event</a> or <a href="./knock-out-competitions">knock-out competition</a> and its days.</li><li>[ ] Go through the <strong>Event details</strong> tabs once. On <strong>Details</strong>: the <strong>Timing card system</strong> (SportIdent or EMIT — it locks when the event starts), a <strong>Course closure</strong> time if you want one, and <strong>Use sub-second timing</strong> only if the race is genuinely timed to fractions. See <a href="./create-event#editing-event-details">Editing event details</a>.</li><li>[ ] For a club training or come-and-try day with no entries beforehand, see <a href="./low-key-events">Low-key events</a>: Manager can make the competitors, and even the courses, from the cards as they&#39;re read.</li><li>[ ] Decide which computer will run the event on the day. If you&#39;re setting it up on a different one, plan to move it (see <a href="#days-before">Days before</a>).</li></ul><p><strong>Courses, classes and controls</strong></p><ul><li>[ ] Import the courses from Purple Pen, OCAD or Condes, or create them by hand. See <a href="./import-event-data">Importing event data</a>.</li><li>[ ] Give every class its course or courses. See <a href="./classes-and-courses#assigning-courses-to-classes">Assigning courses to classes</a>.</li><li>[ ] Set the <strong>Start</strong>, <strong>Finish</strong> and <strong>Check</strong> codes your units use. See <a href="./controls-and-radio-controls#start-finish-and-check-codes">Start, Finish and Check codes</a>. A course with no start or finish unit of its own can start or finish at a numbered control instead; see <a href="./classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>.</li><li>[ ] If you&#39;re using radio controls, mark them and set their priority per class. See <a href="./controls-and-radio-controls#marking-radio-controls-and-setting-their-priority">Marking radio controls</a>.</li><li>[ ] Upload and calibrate the event map, and — for a meshO Prime network — plan where the radios go and check every one has a path back to the Prime. See <a href="./event-map-and-radio-placement">The event map and radio placement</a>.</li></ul><p><strong>Entries</strong></p><ul><li>[ ] Import the entries (Eventor, IOF XML, OJSON or a CSV). See <a href="./import-event-data">Importing event data</a>.</li><li>[ ] Check every competitor has a class and a card number: sort the <strong>Competitors</strong> page by card to find the blanks. See <a href="./import-event-data#what-to-check-after-import">What to check after import</a>.</li><li>[ ] Refresh the <a href="./../reference/competitor-registry">Competitor registry</a> and <a href="./../reference/club-registry">Club registry</a> from Eventor, so names, clubs and cards fill in at the desk.</li><li>[ ] For a seeded draw, import the rankings. See <a href="./import-event-data#importing-rankings">Importing rankings</a>.</li><li>[ ] Allocate bib numbers if you use them. See <a href="./bib-numbers">Bib numbers</a>.</li></ul><h2 id="days-before" tabindex="-1">Days before <a class="header-anchor" href="#days-before" aria-label="Permalink to &quot;Days before&quot;">​</a></h2><p><strong>Start times</strong></p><ul><li>[ ] Draw the start times, leaving gaps for late entries if you take them (<strong>Reserve a gap every N starters</strong>). See <a href="./start-draw">Drawing start times</a>.</li><li>[ ] Clear the <a href="./start-draw#the-start-conflict-summary">start-conflict summary</a> on the Starts screen.</li><li>[ ] Publish the start list: upload it to Eventor, export it, or print it. See <a href="./start-draw#uploading-the-start-list-to-eventor">Uploading the start list to Eventor</a>.</li></ul><p><strong>Results and publishing</strong></p><ul><li>[ ] If elite classes&#39; results are to be held back, set up <a href="./results-quarantine">results quarantine</a> — and set a PIN (below), or the quarantine can&#39;t tell your officials&#39; screens from the public&#39;s.</li><li>[ ] To publish live to liveresultat.orientering.se, create or link the competition on <strong>Event details → Live results</strong>, and decide whether it is made public when the event starts. See <a href="./../running-the-event/publishing-live-results#publishing-to-liveresultat">Publishing to liveresultat</a>.</li><li>[ ] To publish the finished event to the meshO cloud, check <strong>Settings → Cloud sync</strong> and the event&#39;s <strong>Cloud sync</strong> tab. See <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing to the meshO cloud</a>.</li><li>[ ] If another results system reads Manager&#39;s files, turn on the <strong>Live export</strong> on <strong>Event details → Backup &amp; export</strong>. See <a href="./create-event#live-export">Live export</a>.</li><li>[ ] Set up the spectator screens you&#39;ll use. See <a href="./../screens/creating-screens">Creating screens</a>.</li><li>[ ] Decide which info displays you&#39;ll put up — the start clock, the starters list, a radio control&#39;s feed, pending downloads — and on which devices. See <a href="./../screens/info-screens">Event info screens</a>.</li></ul><p><strong>Printing and hire</strong></p><ul><li>[ ] Add your printers in <strong>Settings → Printing</strong>, and choose where each computer&#39;s splits and labels print. Print a test slip. See <a href="./../running-the-event/splits-printing">Printing splits</a> and <a href="./../running-the-event/splits-printing#where-each-computer-s-splits-and-labels-print">Where each computer&#39;s splits and labels print</a>.</li><li>[ ] If you print result labels for a results board, switch them on and choose the label printer. See <a href="./../running-the-event/splits-printing#result-labels-for-the-results-board">Result labels</a>.</li><li>[ ] Put your hire cards in <strong>Settings → Hire card registry</strong>, and other lent items in <strong>Settings → Other hire registry</strong>. See <a href="./../running-the-event/hire-items">Hire items</a>.</li></ul><p><strong>Backups</strong></p><ul><li>[ ] Turn on <strong>auto backup</strong> for the event, and an <strong>external drive backup</strong> onto a USB stick. See <a href="./create-event#backup-export">Backup &amp; export</a> and <a href="./../reference/backup-and-restore">Backup and restore</a>.</li><li>[ ] For a big event, bring a second computer as a <strong>live standby</strong>, pair it in <strong>Settings → Live standby</strong>, and check it reaches <strong>In sync</strong>. See <a href="./../running-the-event/live-standby">Live standby</a>.</li></ul><p><strong>The computer running the event</strong></p><ul><li>[ ] If the event was set up on a different computer, move it now and work through <a href="./moving-an-event">Moving an event to another computer</a>. Remove &quot;(restored)&quot; from its name if it has one.</li><li>[ ] Update meshO Manager on it before the day rather than on it. See <a href="./../download-and-install/#updating">Updating</a>.</li><li>[ ] Set a PIN in <strong>Settings → Access protection</strong> if the event&#39;s network is shared with the public. See <a href="./../reference/settings#access-protection">Access protection</a>.</li><li>[ ] If any computer other than the server will read cards, back up stations or drive its own USB printer, turn on HTTPS in <strong>Settings → Server</strong> and trust the certificate on each of those computers. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a>.</li><li>[ ] Plug in meshO Prime and check it&#39;s found on the <strong>meshO devices</strong> page (the <strong>meshO Radios</strong> icon on the Events list), and that the controls report. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</li><li>[ ] Program the SportIdent units: each control&#39;s code and mode, its switch-off time long enough for the whole day, and its clock set. See <a href="./../reference/station-configuration">Station configuration</a>.</li><li>[ ] Plan the network at the venue: how the download laptops, entry desk, TVs and phones will reach the server computer. See <a href="./../reference/multi-operator-setup">Multi-operator setup</a>.</li><li>[ ] If it&#39;s your first event with Manager, run through the <a href="./../getting-started/first-event-walkthrough">first-event walkthrough</a> with a test event.</li></ul><h2 id="morning-of-the-event" tabindex="-1">Morning of the event <a class="header-anchor" href="#morning-of-the-event" aria-label="Permalink to &quot;Morning of the event&quot;">​</a></h2><p><strong>Before anyone arrives</strong></p><ul><li>[ ] Start the server computer and check Manager is running (the meshO icon in the tray or menu bar).</li><li>[ ] Connect meshO Prime, and check it is switched on for the event (<strong>Event details → Radio controls → meshO Prime</strong>).</li><li>[ ] Plug the external backup drive in.</li><li>[ ] If you have a live standby, start it following the event, and check the <strong>Standby in sync</strong> chip on the main computer.</li></ul><p><strong>Every other device</strong></p><ul><li>[ ] Open Manager on each laptop and tablet from the <strong>Access links</strong> in <strong>Settings → Server</strong> (each has a QR code for phones and tablets): the <strong>IP</strong> link on download and entry-desk laptops, and the <strong>HTTPS</strong> one on any that read cards or print over USB. See <a href="./../reference/server-addresses">Reaching the server</a>.</li><li>[ ] Name each computer when it asks, such as &quot;Download A&quot; or &quot;Entry desk&quot;, so the audit trail can tell them apart and its prints go where you routed them. See <a href="./../reference/audit-trail#naming-a-computer">Naming a computer</a>.</li><li>[ ] At each download desk, connect the card reader and read a test card. See <a href="./../running-the-event/card-download">Card download</a>.</li><li>[ ] Print a test slip from each printer.</li><li>[ ] Open the registration desk and check a card on its reader finds the right person. See <a href="./../running-the-event/late-entries#the-registration-desk">The registration desk</a>.</li><li>[ ] Put the TV screens and info displays up, and check each shows this event.</li></ul><p><strong>Going live</strong></p><ul><li>[ ] Check liveresultat shows the competition, if you publish there.</li><li>[ ] Click <strong>Start event</strong>. If Manager lists <strong>Event validation warnings</strong>, read them and fix what matters before you start. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</li><li>[ ] On the dashboard, check the <strong>Radio controls</strong> card shows every radio control reporting.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./create-event">Creating an event</a></li><li><a href="./import-event-data">Importing event data</a></li><li><a href="./moving-an-event">Moving an event to another computer</a></li><li><a href="./event-map-and-radio-placement">The event map and radio placement</a></li><li><a href="./../running-the-event/publishing-live-results">Publishing live results online</a></li><li><a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a></li><li><a href="./../after-the-event/end-of-event-checklist">End-of-event checklist</a></li></ul>',30)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
